Source code in <code>pyrevitlib/pyrevit/netrequests.py</code> <pre><code>def request(
    method,
    url,
    headers=None,
    params=None,
    data=None,
    json=None,
    stream=False,
    timeout=None,
    verify=None,
    allow_redirects=True,
    **kwargs
):

    if verify is False:
        raise NotImplementedError("verify=False is not supported")

    if allow_redirects is False:
        raise NotImplementedError("allow_redirects=False is not supported")

    client = _shared_client
    temporary_client = False
    req = None

    try:
        url = _apply_params(url, params)

        if timeout is not None:
            try:
                client = HttpClient()
                client.Timeout = TimeSpan.FromSeconds(float(timeout))
                temporary_client = True
            except Exception:
                client = _shared_client
                temporary_client = False

        req = _create_request(method, url, headers=headers, data=data, json_data=json)

        try:
            if stream:
                resp = client.SendAsync(
                    req, HttpCompletionOption.ResponseHeadersRead
                ).Result
            else:
                resp = client.SendAsync(req).Result

        except Exception as ex:
            raise RequestException(
                "HTTP request failed: {}".format(_get_exception_message(ex))
            )

        finally:
            try:
                if req:
                    req.Dispose()
            except Exception:
                pass

        if resp is None:
            raise RequestException("No response received")

        # If streaming, keep the temporary client alive until response.close().
        if stream and temporary_client:
            return Response(resp, stream=True, client=client)

        response = Response(resp, stream=stream, client=None)

        return response

    except RequestException:
        raise

    except Exception as ex:
        import traceback

        raise RequestException(
            "{}\n\n{}".format(_get_exception_message(ex), traceback.format_exc())
        )

    finally:
        # For non-streaming temporary clients, safe to dispose here because
        # response body has already been read into memory.
        if temporary_client and not stream:
            try:
                client.Dispose()
            except Exception:
                pass
